let currentLanguage = "en";
function setLanguage(lang) {
  currentLanguage = lang;
  const toKannada = lang === "kn";
  document.documentElement.lang = toKannada ? "kn" : "en";
  document.querySelectorAll(".language-switch button").forEach(b => b.classList.toggle("selected", b.dataset.lang === lang));
  document.querySelectorAll("input,textarea").forEach(el => {
    if (!el.dataset.originalPlaceholder) el.dataset.originalPlaceholder = el.placeholder || "";
    const original = el.dataset.originalPlaceholder;
    el.placeholder = toKannada ? (attrTranslations[original] || original) : original;
  });
  document.querySelectorAll("option").forEach(el => {
    if (!el.dataset.originalText) el.dataset.originalText = el.textContent;
    const original = el.dataset.originalText;
    el.textContent = toKannada ? (translations[original] || original) : original;
  });
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  let node;
  while ((node = walker.nextNode())) {
    const original = node.nodeValue;
    const trimmed = original.trim();
    if (!trimmed) continue;
    if (!node.__englishText) node.__englishText = original;
    const english = node.__englishText;
    const key = english.trim();
    const translated = translations[key];
    if (toKannada && translated) node.nodeValue = english.replace(key, translated);
    else node.nodeValue = english;
  }
  document.title = toKannada
    ? ({"JalaSeva | Gram Panchayat Water Complaints":"ಜಲಸೇವಾ | ಗ್ರಾಮ ಪಂಚಾಯಿತಿ ನೀರಿನ ದೂರುಗಳು","Submit Complaint | JalaSeva":"ದೂರು ಸಲ್ಲಿಸಿ | ಜಲಸೇವಾ","Track Complaint | JalaSeva":"ದೂರು ಪರಿಶೀಲಿಸಿ | ಜಲಸೇವಾ","Admin Dashboard | JalaSeva":"ನಿರ್ವಾಹಕ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್ | ಜಲಸೇವಾ","Book Water Testing | Gram Panchayat Portal":"ನೀರಿನ ಪರೀಕ್ಷೆ ಬುಕ್ ಮಾಡಿ | ಗ್ರಾಮ ಪಂಚಾಯಿತಿ ಪೋರ್ಟಲ್"}[document.title] || document.title)
    : ({"ಜಲಸೇವಾ | ಗ್ರಾಮ ಪಂಚಾಯಿತಿ ನೀರಿನ ದೂರುಗಳು":"JalaSeva | Gram Panchayat Water Complaints","ದೂರು ಸಲ್ಲಿಸಿ | ಜಲಸೇವಾ":"Submit Complaint | JalaSeva","ದೂರು ಪರಿಶೀಲಿಸಿ | ಜಲಸೇವಾ":"Track Complaint | JalaSeva","ನಿರ್ವಾಹಕ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್ | ಜಲಸೇವಾ":"Admin Dashboard | JalaSeva","ನೀರಿನ ಪರೀಕ್ಷೆ ಬುಕ್ ಮಾಡಿ | ಗ್ರಾಮ ಪಂಚಾಯಿತಿ ಪೋರ್ಟಲ್":"Book Water Testing | Gram Panchayat Portal"}[document.title] || document.title);
  localStorage.setItem("jalaseva_language", lang);
}
document.querySelectorAll(".language-switch button").forEach(button => {
  button.addEventListener("click", () => setLanguage(button.dataset.lang));
});
setLanguage(localStorage.getItem("jalaseva_language") || "en");

const STORAGE_KEY = "jalaseva_complaints";
const RESOLVED_RETENTION_MS = 5 * 24 * 60 * 60 * 1000;
const readComplaints = () => {
  try { return JSON.parse(localStorage.getItem(STORAGE_KEY) || "[]"); }
  catch { return []; }
};
const saveComplaints = items => localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
// Remove resolved complaints five days after they are marked Resolved.
// Older demo records without a resolvedAt date start their five-day period
// when this updated version is first opened, rather than being deleted at once.
function cleanupResolvedComplaints() {
  const now = Date.now();
  let changed = false;
  const items = readComplaints().map(item => {
    if (item.status === "Resolved" && !item.resolvedAt) {
      item.resolvedAt = new Date(now).toISOString();
      changed = true;
    }
    return item;
  });
  const retained = items.filter(item => {
    if (item.status !== "Resolved") return true;
    const resolvedTime = Date.parse(item.resolvedAt);
    return !Number.isFinite(resolvedTime) || now - resolvedTime < RESOLVED_RETENTION_MS;
  });
  if (retained.length !== items.length) changed = true;
  if (changed) saveComplaints(retained);
  return retained;
}
cleanupResolvedComplaints();
// Also check periodically if the portal remains open for several days.
setInterval(cleanupResolvedComplaints, 60 * 1000);
const makeId = () => "JL-" + Math.floor(100000 + Math.random() * 900000);
const escapeHTML = value => String(value ?? "").replace(/[&<>"']/g, ch => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]));
const formatDate = value => new Date(value).toLocaleDateString(currentLanguage === "kn" ? "kn-IN" : "en-IN", {day:"2-digit",month:"short",year:"numeric"});

// Compress an uploaded photo before saving it in this browser's local storage.
function photoToDataURL(file) {
  return new Promise((resolve, reject) => {
    if (!file) return resolve("");
    if (!["image/jpeg", "image/png", "image/webp"].includes(file.type)) {
      reject(new Error(currentLanguage === "kn" ? "JPG, PNG ಅಥವಾ WEBP ಫೋಟೋ ಆಯ್ಕೆಮಾಡಿ." : "Please choose a JPG, PNG or WEBP photo."));
      return;
    }
    if (file.size > 2 * 1024 * 1024) {
      reject(new Error(currentLanguage === "kn" ? "ಫೋಟೋ ಗಾತ್ರ 2 MB ಅಥವಾ ಕಡಿಮೆ ಇರಬೇಕು." : "Photo must be 2 MB or smaller."));
      return;
    }
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("Could not read the selected photo."));
    reader.onload = () => {
      const image = new Image();
      image.onerror = () => reject(new Error("Could not open the selected photo."));
      image.onload = () => {
        const maxSide = 1200;
        const scale = Math.min(1, maxSide / Math.max(image.width, image.height));
        const canvas = document.createElement("canvas");
        canvas.width = Math.max(1, Math.round(image.width * scale));
        canvas.height = Math.max(1, Math.round(image.height * scale));
        canvas.getContext("2d").drawImage(image, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL("image/jpeg", 0.72));
      };
      image.src = reader.result;
    };
    reader.readAsDataURL(file);
  });
}

const photoInput = document.getElementById("complaintPhoto");
if (photoInput) {
  photoInput.addEventListener("change", async () => {
    const preview = document.getElementById("photoPreview");
    const file = photoInput.files[0];
    if (!file) { preview.hidden = true; preview.removeAttribute("src"); return; }
    try {
      const dataURL = await photoToDataURL(file);
      preview.src = dataURL;
      preview.hidden = false;
    } catch (error) {
      photoInput.value = "";
      preview.hidden = true;
      alert(error.message);
    }
  });
}

// Optional GPS location: requested only after the resident clicks the button.
let complaintCoordinates = null;
const currentLocationButton = document.getElementById("useCurrentLocation");
if (currentLocationButton) {
  currentLocationButton.addEventListener("click", () => {
    const status = document.getElementById("locationMessage");
    if (!navigator.geolocation) {
      status.textContent = currentLanguage === "kn"
        ? "ಈ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಸ್ಥಳ ಸೌಲಭ್ಯ ಲಭ್ಯವಿಲ್ಲ."
        : "Location is not supported by this browser.";
      return;
    }
    currentLocationButton.disabled = true;
    status.textContent = currentLanguage === "kn" ? "ನಿಮ್ಮ ಸ್ಥಳ ಪಡೆಯಲಾಗುತ್ತಿದೆ..." : "Getting your current location...";
    navigator.geolocation.getCurrentPosition(
      position => {
        complaintCoordinates = {
          latitude: Number(position.coords.latitude.toFixed(6)),
          longitude: Number(position.coords.longitude.toFixed(6))
        };
        status.textContent = currentLanguage === "kn"
          ? `ಸ್ಥಳ ಸೇರಿಸಲಾಗಿದೆ: ${complaintCoordinates.latitude}, ${complaintCoordinates.longitude}`
          : `Location added: ${complaintCoordinates.latitude}, ${complaintCoordinates.longitude}`;
        currentLocationButton.disabled = false;
      },
      error => {
        const message = error.code === 1
          ? (currentLanguage === "kn" ? "ಸ್ಥಳ ಅನುಮತಿಯನ್ನು ನಿರಾಕರಿಸಲಾಗಿದೆ. ಬ್ರೌಸರ್ ಸೆಟ್ಟಿಂಗ್‌ನಲ್ಲಿ ಅನುಮತಿಸಿ." : "Location permission was denied. Allow location access in your browser settings.")
          : (currentLanguage === "kn" ? "ಸ್ಥಳ ಪಡೆಯಲಾಗಲಿಲ್ಲ. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ." : "Could not get your location. Please try again.");
        status.textContent = message;
        currentLocationButton.disabled = false;
      },
      { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }
    );
  });
}

const complaintForm = document.getElementById("complaintForm");
if (complaintForm) {
  complaintForm.addEventListener("submit", async event => {
    event.preventDefault();
    const message = document.getElementById("formMessage");
    const data = new FormData(complaintForm);
    let photo = "";
    try {
      photo = await photoToDataURL(data.get("photo"));
    } catch (error) {
      message.className = "form-message error";
      message.textContent = error.message;
      return;
    }
    const complaint = {
      id: makeId(), name: data.get("name").trim(), phone: data.get("phone").trim(),
      village: data.get("village").trim(), type: data.get("type"),
      location: data.get("location").trim(), description: data.get("description").trim(),
      photo, coordinates: complaintCoordinates,
      date: new Date().toISOString(), status: "Pending", history:[{status:"Pending",at:new Date().toISOString()}]
    };
    const all = readComplaints(); all.unshift(complaint);
    try { saveComplaints(all); } catch (error) {
      message.className = "form-message error";
      message.textContent = currentLanguage === "kn" ? "ಸಂಗ್ರಹಣಾ ಸ್ಥಳ ತುಂಬಿದೆ. ಚಿಕ್ಕ ಫೋಟೋ ಬಳಸಿ." : "Browser storage is full. Please use a smaller photo.";
      return;
    }
    complaintForm.reset();
    complaintCoordinates = null;
    const locationMessage = document.getElementById("locationMessage");
    if (locationMessage) locationMessage.textContent = currentLanguage === "kn"
      ? "ಪ್ರಸ್ತುತ GPS ಸ್ಥಳವನ್ನು ಸೇರಿಸಲು ಬಟನ್ ಒತ್ತಿರಿ (ಐಚ್ಛಿಕ)."
      : "Click the button to attach your current GPS location (optional).";
    message.className = "form-message success";
    message.innerHTML = currentLanguage === "kn" ? `ದೂರು ಯಶಸ್ವಿಯಾಗಿ ಸಲ್ಲಿಸಲಾಗಿದೆ. ನಿಮ್ಮ ದೂರು ಸಂಖ್ಯೆ <strong>${escapeHTML(complaint.id)}</strong>. ದೂರಿನ ಸ್ಥಿತಿಯನ್ನು ಪರಿಶೀಲಿಸಲು ಈ ಸಂಖ್ಯೆಯನ್ನು ಉಳಿಸಿಕೊಳ್ಳಿ.` : `Complaint submitted successfully. Your complaint ID is <strong>${escapeHTML(complaint.id)}</strong>. Save this ID to track your complaint.`;
  });
}

const trackForm = document.getElementById("trackForm");
if (trackForm) {
  trackForm.addEventListener("submit", event => {
    event.preventDefault();
    const id = new FormData(trackForm).get("complaintId").trim().toUpperCase();
    const item = cleanupResolvedComplaints().find(c => c.id.toUpperCase() === id);
    const result = document.getElementById("trackResult");
    if (!item) {
      result.innerHTML = currentLanguage === "kn" ? '<div class="result-card"><b>ದೂರು ಕಂಡುಬಂದಿಲ್ಲ.</b><p>ದೂರು ಸಂಖ್ಯೆಯನ್ನು ಪರಿಶೀಲಿಸಿ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ. ಈ ಮಾದರಿಯಲ್ಲಿ ದಾಖಲೆಗಳು ಅದೇ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಮಾತ್ರ ಉಳಿಯುತ್ತವೆ.</p></div>' : '<div class="result-card"><b>Complaint not found.</b><p>Please check the ID and try again. This demo stores records only in the same browser.</p></div>'; 
      return;
    }
    const cls = item.status.toLowerCase().replace(" ", "-");
    const history = item.history || [{status:"Pending",at:item.date}];
    const labels = currentLanguage === "kn" ? {"Pending":"ಬಾಕಿ","In Progress":"ಪ್ರಗತಿಯಲ್ಲಿದೆ","Resolved":"ಪರಿಹರಿಸಲಾಗಿದೆ"} : {};
    result.innerHTML = `<article class="result-card"><div class="result-head"><h3>${escapeHTML(item.id)}</h3><span class="status ${cls}">${escapeHTML(labels[item.status] || item.status)}</span></div><div class="result-meta"><span>📍 ${escapeHTML(item.village)} · ${escapeHTML(item.location)}${item.coordinates ? ` · <a href="https://www.google.com/maps?q=${item.coordinates.latitude},${item.coordinates.longitude}" target="_blank" rel="noopener">View map</a>` : ""}</span><span>📅 ${formatDate(item.date)}</span></div><p><b>${escapeHTML(item.type)}</b> — ${escapeHTML(item.description)}</p>${item.photo ? `<img class="complaint-photo" src="${item.photo}" alt="Uploaded complaint photo">` : ""}<p>${currentLanguage === "kn" ? "ಸಲ್ಲಿಸಿದವರು" : "Submitted by"} ${escapeHTML(item.name)}</p><h3>${currentLanguage === "kn" ? "ದೂರು ಕಾಲರೇಖೆ" : "Complaint timeline"}</h3><ol class="timeline">${history.map(h=>`<li><b>${escapeHTML(labels[h.status]||h.status)}</b><small>${formatDate(h.at)}</small></li>`).join("")}</ol><h3>${currentLanguage === "kn" ? "ಅಧಿಸೂಚನೆಗಳು" : "Notifications"}</h3><p>${currentLanguage === "kn" ? "ನಿಮ್ಮ ದೂರು ಸ್ಥಿತಿ ನವೀಕರಿಸಲಾಗಿದೆ:" : "Your complaint status was updated:"} <b>${escapeHTML(labels[item.status]||item.status)}</b></p></article>`;
    const fb=document.getElementById("customerFeedback");
    if(item.status === "Resolved") { fb.innerHTML = `<form id="feedbackForm" class="panel feedback-panel"><h3>${currentLanguage === "kn" ? "ನಿಮ್ಮ ಪ್ರತಿಕ್ರಿಯೆ" : "Customer feedback"}</h3><label>${currentLanguage === "kn" ? "ಪರಿಹಾರಕ್ಕೆ ರೇಟಿಂಗ್ ನೀಡಿ" : "Rate the resolution"}<select name="rating" required><option value="">${currentLanguage === "kn" ? "ರೇಟಿಂಗ್ ಆಯ್ಕೆಮಾಡಿ" : "Choose rating"}</option><option value="5">5 - Excellent</option><option value="4">4 - Good</option><option value="3">3 - Average</option><option value="2">2 - Poor</option><option value="1">1 - Very poor</option></select></label><label>${currentLanguage === "kn" ? "ನಿಮ್ಮ ಪ್ರತಿಕ್ರಿಯೆ" : "Your feedback"}<textarea name="comment" rows="3"></textarea></label><button class="btn primary">${currentLanguage === "kn" ? "ಪ್ರತಿಕ್ರಿಯೆ ಸಲ್ಲಿಸಿ" : "Submit feedback"}</button><p id="feedbackMessage"></p></form>`; document.getElementById("feedbackForm").addEventListener("submit",e=>{e.preventDefault();const a=readComplaints();const c=a.find(x=>x.id===item.id);c.feedback={rating:new FormData(e.target).get("rating"),comment:new FormData(e.target).get("comment"),at:new Date().toISOString()};saveComplaints(a);document.getElementById("feedbackMessage").textContent=currentLanguage==="kn"?"ನಿಮ್ಮ ಪ್ರತಿಕ್ರಿಯೆಗೆ ಧನ್ಯವಾದಗಳು.":"Thank you for your feedback.";}); } else fb.innerHTML="";
  });
}

function renderAdmin() {
  const rows = document.getElementById("complaintRows");
  if (!rows) return;
  const items = cleanupResolvedComplaints();
  document.getElementById("totalCount").textContent = items.length;
  document.getElementById("pendingCount").textContent = items.filter(x=>x.status==="Pending").length;
  document.getElementById("progressCount").textContent = items.filter(x=>x.status==="In Progress").length;
  document.getElementById("resolvedCount").textContent = items.filter(x=>x.status==="Resolved").length;
  document.getElementById("emptyState").hidden = items.length > 0;
  rows.innerHTML = items.map(c => `<tr><td><b>${escapeHTML(c.id)}</b></td><td>${escapeHTML(c.name)}</td><td>${escapeHTML(c.type)}</td><td>${escapeHTML(c.village)}${c.coordinates ? `<br><a href="https://www.google.com/maps?q=${c.coordinates.latitude},${c.coordinates.longitude}" target="_blank" rel="noopener">View map</a>` : ""}</td><td>${c.photo ? `<a href="${c.photo}" target="_blank" rel="noopener"><img class="admin-photo-thumb" src="${c.photo}" alt="Complaint photo"></a>` : "—"}</td><td>${formatDate(c.date)}</td><td><span class="status ${c.status.toLowerCase().replace(" ","-")}">${escapeHTML(c.status)}</span></td><td><select data-id="${escapeHTML(c.id)}" aria-label="Update ${escapeHTML(c.id)} status"><option ${c.status==="Pending"?"selected":""}>Pending</option><option ${c.status==="In Progress"?"selected":""}>In Progress</option><option ${c.status==="Resolved"?"selected":""}>Resolved</option></select></td></tr>`).join("");
  rows.querySelectorAll("select").forEach(select => select.addEventListener("change", () => {
    const all = readComplaints();
    const item = all.find(c => c.id === select.dataset.id);
    if (item) {
      item.status = select.value;
      item.history = item.history || [{status:"Pending",at:item.date}];
      item.history.push({status:select.value,at:new Date().toISOString()});
      if (select.value === "Resolved") item.resolvedAt = new Date().toISOString();
      else delete item.resolvedAt;
      saveComplaints(all); renderAdmin(); setLanguage(currentLanguage);
    }
  }));
}

// Water testing appointment booking (prototype: browser localStorage only).
const APPOINTMENT_KEY = "jalaseva_water_test_appointments";
const readAppointments = () => { try { return JSON.parse(localStorage.getItem(APPOINTMENT_KEY) || "[]"); } catch { return []; } };
const saveAppointments = items => localStorage.setItem(APPOINTMENT_KEY, JSON.stringify(items));
const appointmentForm = document.getElementById("appointmentForm");
if (appointmentForm) {
  const dateInput = document.getElementById("appointmentDate");
  if (dateInput) { const today = new Date(); dateInput.min = new Date(today.getTime()-today.getTimezoneOffset()*60000).toISOString().slice(0,10); }
  appointmentForm.addEventListener("submit", event => {
    event.preventDefault();
    const data = new FormData(appointmentForm);
    const requestedDate = data.get("date");
    if (new Date(requestedDate + "T00:00:00") < new Date(new Date().getFullYear(), new Date().getMonth(), new Date().getDate())) { document.getElementById("appointmentMessage").textContent = currentLanguage === "kn" ? "ದಯವಿಟ್ಟು ಮುಂದಿನ ದಿನಾಂಕ ಆಯ್ಕೆಮಾಡಿ." : "Please choose a future date."; return; }
    const booking = { id:"WT-" + Math.floor(100000 + Math.random()*900000), name:data.get("name").trim(), phone:data.get("phone").trim(), village:data.get("village").trim(), source:data.get("source"), testType:data.get("testType"), date:requestedDate, slot:data.get("slot"), address:data.get("address").trim(), details:data.get("details").trim(), status:"Requested", createdAt:new Date().toISOString() };
    const all = readAppointments(); all.unshift(booking); saveAppointments(all); appointmentForm.reset();
    const msg = document.getElementById("appointmentMessage"); msg.className = "form-message success";
    msg.innerHTML = `${currentLanguage === "kn" ? "ಅಪಾಯಿಂಟ್‌ಮೆಂಟ್ ಮನವಿ ಸಲ್ಲಿಸಲಾಗಿದೆ. ನಿಮ್ಮ ಅಪಾಯಿಂಟ್‌ಮೆಂಟ್ ಸಂಖ್ಯೆ" : "Appointment request submitted. Your appointment ID is"} <strong>${escapeHTML(booking.id)}</strong>. ${currentLanguage === "kn" ? "ಸ್ಥಿತಿ ಪರಿಶೀಲಿಸಲು ಈ ಸಂಖ್ಯೆಯನ್ನು ಉಳಿಸಿಕೊಳ್ಳಿ." : "Save this ID to check the status."}`;
  });
}
const appointmentLookup = document.getElementById("appointmentLookup");
if (appointmentLookup) appointmentLookup.addEventListener("submit", event => {
  event.preventDefault(); const id = new FormData(appointmentLookup).get("appointmentId").trim().toUpperCase();
  const item = readAppointments().find(a => a.id.toUpperCase() === id); const target = document.getElementById("appointmentLookupResult");
  if (!item) { target.innerHTML = `<div class="appointment-result">${currentLanguage === "kn" ? "ಈ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಅಪಾಯಿಂಟ್‌ಮೆಂಟ್ ಕಂಡುಬಂದಿಲ್ಲ." : "Appointment not found in this browser."}</div>`; return; }
  target.innerHTML = `<div class="appointment-result"><b>${currentLanguage === "kn" ? "ಅಪಾಯಿಂಟ್‌ಮೆಂಟ್ ಸ್ಥಿತಿ" : "Appointment status"}: ${escapeHTML(item.status)}</b><br>${currentLanguage === "kn" ? "ಅಪಾಯಿಂಟ್‌ಮೆಂಟ್ ದಿನಾಂಕ" : "Appointment date"}: ${escapeHTML(item.date)}<br>${currentLanguage === "kn" ? "ಸಮಯ" : "Time slot"}: ${escapeHTML(item.slot)}<br>${escapeHTML(item.source)} · ${escapeHTML(item.testType)}</div>`;
});
function renderAppointments() {
  const rows = document.getElementById("appointmentRows"); if (!rows) return; const items = readAppointments();
  const empty = document.getElementById("appointmentEmptyState"); if (empty) empty.hidden = items.length > 0;
  rows.innerHTML = items.map(a => `<tr><td><b>${escapeHTML(a.id)}</b></td><td>${escapeHTML(a.name)}</td><td>${escapeHTML(a.phone)}</td><td>${escapeHTML(a.village)}<br>${escapeHTML(a.address)}</td><td>${escapeHTML(a.source)}<br>${escapeHTML(a.testType)}</td><td>${escapeHTML(a.date)}<br>${escapeHTML(a.slot)}</td><td><span class="status ${a.status.toLowerCase()}">${escapeHTML(a.status)}</span></td><td><select data-appointment-id="${escapeHTML(a.id)}" aria-label="Update ${escapeHTML(a.id)} status"><option ${a.status==="Requested"?"selected":""}>Requested</option><option ${a.status==="Confirmed"?"selected":""}>Confirmed</option><option ${a.status==="Completed"?"selected":""}>Completed</option><option ${a.status==="Cancelled"?"selected":""}>Cancelled</option></select></td></tr>`).join("");
  rows.querySelectorAll("select").forEach(select => select.addEventListener("change", () => { const all=readAppointments(); const item=all.find(a=>a.id===select.dataset.appointmentId); if(item){item.status=select.value;saveAppointments(all);renderAppointments();setLanguage(currentLanguage);} }));
}

